import{_ as e,o as l,c as t,a5 as i}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"《文明 现代化 价值投资与中国》读书笔记","description":"","frontmatter":{"date":"2022-04-01T20:35:02","title":"《文明 现代化 价值投资与中国》读书笔记","categories":["写作","作业","价值投资"],"tags":["写作","作业","价值投资"]},"headers":[{"level":2,"title":"资产管理服务是服务性行业，他和其他服务业相比不一样的地方在哪里？","slug":"资产管理服务是服务性行业-他和其他服务业相比不一样的地方在哪里","link":"#资产管理服务是服务性行业-他和其他服务业相比不一样的地方在哪里","children":[]},{"level":2,"title":"从长期来看，哪些金融资产可以让财富持续、有效、安全、可靠地增长？","slug":"从长期来看-哪些金融资产可以让财富持续、有效、安全、可靠地增长","link":"#从长期来看-哪些金融资产可以让财富持续、有效、安全、可靠地增长","children":[]},{"level":2,"title":"为什么是经济在过去200年出现了持续性、累进性的，长期复利性的增长和发展？","slug":"为什么是经济在过去200年出现了持续性、累进性的-长期复利性的增长和发展","link":"#为什么是经济在过去200年出现了持续性、累进性的-长期复利性的增长和发展","children":[]},{"level":2,"title":"为什么说定投是投资的正道、大道？","slug":"为什么说定投是投资的正道、大道","link":"#为什么说定投是投资的正道、大道","children":[]},{"level":2,"title":"为什么李录认为，价值投资在中国依然适用？定投适用中国股票交易市场吗？","slug":"为什么李录认为-价值投资在中国依然适用-定投适用中国股票交易市场吗","link":"#为什么李录认为-价值投资在中国依然适用-定投适用中国股票交易市场吗","children":[]},{"level":2,"title":"价值投资的基本内容（常识）包括哪四项？","slug":"价值投资的基本内容-常识-包括哪四项","link":"#价值投资的基本内容-常识-包括哪四项","children":[]},{"level":2,"title":"股市中，投资者和投机者最大的区别是什么？两种行为的结果有何区别？","slug":"股市中-投资者和投机者最大的区别是什么-两种行为的结果有何区别","link":"#股市中-投资者和投机者最大的区别是什么-两种行为的结果有何区别","children":[]},{"level":2,"title":"能力圈是什么？如何建立？","slug":"能力圈是什么-如何建立","link":"#能力圈是什么-如何建立","children":[]},{"level":2,"title":"在作者看来，价值投资人的品性是什么？你赞同他的看法吗？作为一个定投践行者，你的品性又是什么？","slug":"在作者看来-价值投资人的品性是什么-你赞同他的看法吗-作为一个定投践行者-你的品性又是什么","link":"#在作者看来-价值投资人的品性是什么-你赞同他的看法吗-作为一个定投践行者-你的品性又是什么","children":[]},{"level":2,"title":"践行定投，如何做到知行合一？","slug":"践行定投-如何做到知行合一","link":"#践行定投-如何做到知行合一","children":[]},{"level":2,"title":"为什么说投资是一个发现自己的过程？发现自己的什么？","slug":"为什么说投资是一个发现自己的过程-发现自己的什么","link":"#为什么说投资是一个发现自己的过程-发现自己的什么","children":[]},{"level":2,"title":"“知识的诚实”是什么意思？和能力圈概念有什么关系？和践行定投有什么关系？","slug":"知识的诚实-是什么意思-和能力圈概念有什么关系-和践行定投有什么关系","link":"#知识的诚实-是什么意思-和能力圈概念有什么关系-和践行定投有什么关系","children":[]},{"level":2,"title":"为什么价值投资者只占据交易市场的5%（少数派），但他们确是市场存在的理由？为什么各位践行定投，更是少数派中的少数派？","slug":"为什么价值投资者只占据交易市场的5-少数派-但他们确是市场存在的理由-为什么各位践行定投-更是少数派中的少数派","link":"#为什么价值投资者只占据交易市场的5-少数派-但他们确是市场存在的理由-为什么各位践行定投-更是少数派中的少数派","children":[]},{"level":2,"title":"既然投机活动最终结果会归零，为什么还有这么多的人趋之若鹜参与投机活动？（交易市场95%的人是投机分子）如何避免自己成为95%中的一员？","slug":"既然投机活动最终结果会归零-为什么还有这么多的人趋之若鹜参与投机活动-交易市场95-的人是投机分子-如何避免自己成为95-中的一员","link":"#既然投机活动最终结果会归零-为什么还有这么多的人趋之若鹜参与投机活动-交易市场95-的人是投机分子-如何避免自己成为95-中的一员","children":[]},{"level":2,"title":"既然价值投资是金矿、是康庄大道，为什么大多数人不愿意走这条路？（交易市场95%的人是投机分子）为什么你愿意走定投这条少有人走的路？","slug":"既然价值投资是金矿、是康庄大道-为什么大多数人不愿意走这条路-交易市场95-的人是投机分子-为什么你愿意走定投这条少有人走的路","link":"#既然价值投资是金矿、是康庄大道-为什么大多数人不愿意走这条路-交易市场95-的人是投机分子-为什么你愿意走定投这条少有人走的路","children":[]},{"level":2,"title":"现代化的本质和铁律是什么？","slug":"现代化的本质和铁律是什么","link":"#现代化的本质和铁律是什么","children":[]},{"level":2,"title":"为什么现代化没有可能在中国诞生？","slug":"为什么现代化没有可能在中国诞生","link":"#为什么现代化没有可能在中国诞生","children":[]},{"level":2,"title":"中西方历史文化最明显的差异是什么？背后的原因又是什么？","slug":"中西方历史文化最明显的差异是什么-背后的原因又是什么","link":"#中西方历史文化最明显的差异是什么-背后的原因又是什么","children":[]},{"level":2,"title":"作者看来，中国近代现代化进程（78年后的经济腾飞）的原因是什么？","slug":"作者看来-中国近代现代化进程-78年后的经济腾飞-的原因是什么","link":"#作者看来-中国近代现代化进程-78年后的经济腾飞-的原因是什么","children":[]},{"level":2,"title":"了解现代化本质和中国现代化进程，对你实施定投有什么启示？","slug":"了解现代化本质和中国现代化进程-对你实施定投有什么启示","link":"#了解现代化本质和中国现代化进程-对你实施定投有什么启示","children":[]}],"relativePath":"posts/homework/127.md","filePath":"posts/homework/127.md"}'),r={name:"posts/homework/127.md"};function h(n,a,o,d,s,p){return l(),t("div",null,[...a[0]||(a[0]=[i('<p>3月定投课堂读书会的书目是《文明 现代化 价值投资与中国》。价值投资理论不难，但真正做到的人不多，如果你能做到的话能就是世界前5%的人。</p><h1 id="第一周" tabindex="-1">第一周 <a class="header-anchor" href="#第一周" aria-label="Permalink to &quot;第一周&quot;">​</a></h1><h2 id="资产管理服务是服务性行业-他和其他服务业相比不一样的地方在哪里" tabindex="-1">资产管理服务是服务性行业，他和其他服务业相比不一样的地方在哪里？ <a class="header-anchor" href="#资产管理服务是服务性行业-他和其他服务业相比不一样的地方在哪里" aria-label="Permalink to &quot;资产管理服务是服务性行业，他和其他服务业相比不一样的地方在哪里？&quot;">​</a></h2><p>资产管理服务和其他服务业两个主要的不同点：1.在绝大多数时间里不知道、也无法判断产品的好坏。2.行业的总体报酬高于其他几乎所有行业。</p><h2 id="从长期来看-哪些金融资产可以让财富持续、有效、安全、可靠地增长" tabindex="-1">从长期来看，哪些金融资产可以让财富持续、有效、安全、可靠地增长？ <a class="header-anchor" href="#从长期来看-哪些金融资产可以让财富持续、有效、安全、可靠地增长" aria-label="Permalink to &quot;从长期来看，哪些金融资产可以让财富持续、有效、安全、可靠地增长？&quot;">​</a></h2><p>从长期来看，股票可以让财富持续、有效、安全、可靠地增长，有两个原因，一个是通货膨胀，另一个是经济的增长。</p><h2 id="为什么是经济在过去200年出现了持续性、累进性的-长期复利性的增长和发展" tabindex="-1">为什么是经济在过去200年出现了持续性、累进性的，长期复利性的增长和发展？ <a class="header-anchor" href="#为什么是经济在过去200年出现了持续性、累进性的-长期复利性的增长和发展" aria-label="Permalink to &quot;为什么是经济在过去200年出现了持续性、累进性的，长期复利性的增长和发展？&quot;">​</a></h2><p>过去300年现代科学技术与现代化自由市场相结合，形成3.0文明，产生1+1&gt;2和1+1&gt;4两种效果的叠加。</p><h2 id="为什么说定投是投资的正道、大道" tabindex="-1">为什么说定投是投资的正道、大道？ <a class="header-anchor" href="#为什么说定投是投资的正道、大道" aria-label="Permalink to &quot;为什么说定投是投资的正道、大道？&quot;">​</a></h2><p>针对某个投资标的在很长的时间内定期投资一定的金额。实际上会长期持有某个标的，属于是价值投资。</p><p>正道是可持续的东西，可持续的东西有一个共同的特点，就是你得到的东西在所有其他人看来，都是你应得的东西。</p><p>价值投资是投资公司的所有权，帮助公司的市值更接近真实的内在价值，对公司有帮助。公司自身的内在价值不断增长，自己可以分得公司的部分增长，同时未客户提更持续、可靠、安全的回报。最后的结果是帮助了经济，帮助了公司，帮助了个人，也在这个过程中帮助了自己。</p><h2 id="为什么李录认为-价值投资在中国依然适用-定投适用中国股票交易市场吗" tabindex="-1">为什么李录认为，价值投资在中国依然适用？定投适用中国股票交易市场吗？ <a class="header-anchor" href="#为什么李录认为-价值投资在中国依然适用-定投适用中国股票交易市场吗" aria-label="Permalink to &quot;为什么李录认为，价值投资在中国依然适用？定投适用中国股票交易市场吗？&quot;">​</a></h2><p>未来中国会继续在3.0文明的主航道上走下去应该是大概率的事情。因为她离开的成本会非常非常高。真正的2.0文明的主要其实和政治、文化关系不大，而和自由市场经济及现代科技关系极大，这是真正的本质。经济依然会持续累进式的增长，连带着出现通货膨胀，股票依然会优于其他各大类金融资产，价值投资仍然是正道、大道，有因为中国市场还处在不成熟阶段，反而为价值投资提供了更多优势。</p><h1 id="第二周" tabindex="-1">第二周 <a class="header-anchor" href="#第二周" aria-label="Permalink to &quot;第二周&quot;">​</a></h1><h2 id="价值投资的基本内容-常识-包括哪四项" tabindex="-1">价值投资的基本内容（常识）包括哪四项？ <a class="header-anchor" href="#价值投资的基本内容-常识-包括哪四项" aria-label="Permalink to &quot;价值投资的基本内容（常识）包括哪四项？&quot;">​</a></h2><p>价值投资的基本概念包括，第一，股票是对公司的部分所有权，而不只是买卖的证券；第二，安全边际；第三，市场先生；第四，能力圈。</p><h2 id="股市中-投资者和投机者最大的区别是什么-两种行为的结果有何区别" tabindex="-1">股市中，投资者和投机者最大的区别是什么？两种行为的结果有何区别？ <a class="header-anchor" href="#股市中-投资者和投机者最大的区别是什么-两种行为的结果有何区别" aria-label="Permalink to &quot;股市中，投资者和投机者最大的区别是什么？两种行为的结果有何区别？&quot;">​</a></h2><p>投资者预测公司本身未来的表现，投机者预测股市中其他参与者在短期之内的行为。</p><p>对投资者而言，如果投资的是持续成长的公司，投资回报也会持续增长。对于投机者而言，如果只是猜测他人在短期之内的买卖行为，到最后只可能有一种结果：输赢相等，零和的结果。</p><h2 id="能力圈是什么-如何建立" tabindex="-1">能力圈是什么？如何建立？ <a class="header-anchor" href="#能力圈是什么-如何建立" aria-label="Permalink to &quot;能力圈是什么？如何建立？&quot;">​</a></h2><p>能力圈是能够对某些公司、某些行业获得比几乎所有人更深的理解，而且能够对公司未来长期的表现，做出比所有其他人更准确的判断，在这个圈子里面就是自己的独特能力，其最重要的就是边界，每个人的能力圈都不一样。</p><p>如何建立能力圈，建立安全边界，投资自己真知道的东西；按所有者的角度看生意；慢慢积累知识，抱有对知识的诚实的态度；让自己的兴趣和机会来主导研究。</p><h2 id="在作者看来-价值投资人的品性是什么-你赞同他的看法吗-作为一个定投践行者-你的品性又是什么" tabindex="-1">在作者看来，价值投资人的品性是什么？你赞同他的看法吗？作为一个定投践行者，你的品性又是什么？ <a class="header-anchor" href="#在作者看来-价值投资人的品性是什么-你赞同他的看法吗-作为一个定投践行者-你的品性又是什么" aria-label="Permalink to &quot;在作者看来，价值投资人的品性是什么？你赞同他的看法吗？作为一个定投践行者，你的品性又是什么？&quot;">​</a></h2><p>一个优秀的投资人的必备品性：要有极度的耐心，机会没来的时候就认真学习，但是机会到来的时候，又有强烈的果决力和行动能力。</p><p>我赞同作者的看法，一个有极度耐心的人必然会培养出长期视角，而在不断学习和思考的过程中，肯定会形成自己特立独行且正确的思考，此时的行动是自然而然的事情，但对外人来说可能需要十足的勇气或者冒险。</p><p>自己有耐心，能静下心来做事，正在不断的锻炼自己的耐心和长期视角。</p><h2 id="践行定投-如何做到知行合一" tabindex="-1">践行定投，如何做到知行合一？ <a class="header-anchor" href="#践行定投-如何做到知行合一" aria-label="Permalink to &quot;践行定投，如何做到知行合一？&quot;">​</a></h2><p>知行合一其实是跨过知道与做到的距离。定投是用很长的时间去学习、观察、实践、以及修正。在这个过程中保持足够的耐心，接受自己的笨拙，不完美，边学边做，边学边培养自己的兴趣。</p><p>学习：让自己的兴趣来引导，用科学的方法，诚实的态度缓慢的、一点一滴的去积累知识。</p><h1 id="第三周" tabindex="-1">第三周 <a class="header-anchor" href="#第三周" aria-label="Permalink to &quot;第三周&quot;">​</a></h1><h2 id="为什么说投资是一个发现自己的过程-发现自己的什么" tabindex="-1">为什么说投资是一个发现自己的过程？发现自己的什么？ <a class="header-anchor" href="#为什么说投资是一个发现自己的过程-发现自己的什么" aria-label="Permalink to &quot;为什么说投资是一个发现自己的过程？发现自己的什么？&quot;">​</a></h2><p>投资是对未来的预测，然而未来本质上却是无法预测的，所以预测就是概率。因此，你能比别人做得更好的唯一方式就是尽可能地掌握所有的事实，并且真正做到知己所知，知己所不知，建立概率优势，在此道路上坚持不懈的努力工作。</p><p>投资其实是一个发现自己的过程：我是谁，我的兴趣是什么，我擅长什么，喜欢做什么事，进而将这些优势不断强化放大，知道自己超越其他人，取得相当可观的优势。</p><h2 id="知识的诚实-是什么意思-和能力圈概念有什么关系-和践行定投有什么关系" tabindex="-1">“知识的诚实”是什么意思？和能力圈概念有什么关系？和践行定投有什么关系？ <a class="header-anchor" href="#知识的诚实-是什么意思-和能力圈概念有什么关系-和践行定投有什么关系" aria-label="Permalink to &quot;“知识的诚实”是什么意思？和能力圈概念有什么关系？和践行定投有什么关系？&quot;">​</a></h2><p>“知识的诚实”需要知己所知，更重要的是需要知己所不知。</p><p>能力圈重要的概念就是边界，边界内是自己知道的，自己的优势，边界外是自己不知道的。</p><p>其实能力圈是一个动态的圈，践行定投就是不断在做中学习，在做中找到兴趣和乐趣，不断的发现自己，成长自己，扩宽自己的能力圈。</p><h2 id="为什么价值投资者只占据交易市场的5-少数派-但他们确是市场存在的理由-为什么各位践行定投-更是少数派中的少数派" tabindex="-1">为什么价值投资者只占据交易市场的5%（少数派），但他们确是市场存在的理由？为什么各位践行定投，更是少数派中的少数派？ <a class="header-anchor" href="#为什么价值投资者只占据交易市场的5-少数派-但他们确是市场存在的理由-为什么各位践行定投-更是少数派中的少数派" aria-label="Permalink to &quot;为什么价值投资者只占据交易市场的5%（少数派），但他们确是市场存在的理由？为什么各位践行定投，更是少数派中的少数派？&quot;">​</a></h2><p>市场存在的首要任务是为社会提供非常有用的功能。基本面投资人为市场长期的价格发现机制提供了基础，并促进市场的不断壮大。</p><p>价值投资有个重要的基本概念是安全边际，这个安全边际实际上是一种择时，选择资产对于投资人来说的合理价值空间，而定投其实没那么关注择时，低也卖，高也卖，定投的安全边际是蛋壳投资，更关注的是时长。</p><h2 id="既然投机活动最终结果会归零-为什么还有这么多的人趋之若鹜参与投机活动-交易市场95-的人是投机分子-如何避免自己成为95-中的一员" tabindex="-1">既然投机活动最终结果会归零，为什么还有这么多的人趋之若鹜参与投机活动？（交易市场95%的人是投机分子）如何避免自己成为95%中的一员？ <a class="header-anchor" href="#既然投机活动最终结果会归零-为什么还有这么多的人趋之若鹜参与投机活动-交易市场95-的人是投机分子-如何避免自己成为95-中的一员" aria-label="Permalink to &quot;既然投机活动最终结果会归零，为什么还有这么多的人趋之若鹜参与投机活动？（交易市场95%的人是投机分子）如何避免自己成为95%中的一员？&quot;">​</a></h2><p>股票市场的可交易的特征刚好契合人性中的懒惰、贪婪和投机心理，这就是市场机制形成的关键 。</p><p>投资本身是一个孤独的过程，是自己做决定的事，是一个人的奥德赛。选择了好的生意，它自己会照顾自己，把自己充足的精力放到读书，健身，帮朋友，陪家人上面。</p><h2 id="既然价值投资是金矿、是康庄大道-为什么大多数人不愿意走这条路-交易市场95-的人是投机分子-为什么你愿意走定投这条少有人走的路" tabindex="-1">既然价值投资是金矿、是康庄大道，为什么大多数人不愿意走这条路？（交易市场95%的人是投机分子）为什么你愿意走定投这条少有人走的路？ <a class="header-anchor" href="#既然价值投资是金矿、是康庄大道-为什么大多数人不愿意走这条路-交易市场95-的人是投机分子-为什么你愿意走定投这条少有人走的路" aria-label="Permalink to &quot;既然价值投资是金矿、是康庄大道，为什么大多数人不愿意走这条路？（交易市场95%的人是投机分子）为什么你愿意走定投这条少有人走的路？&quot;">​</a></h2><p>价值投资需要经过很长的时间才能验证，而市场中的大多数人，希望通过短期交易，“轻松”的赚快钱。</p><p>知道自己没能力赚快钱，相信复利的力量。</p><h1 id="第四周" tabindex="-1">第四周 <a class="header-anchor" href="#第四周" aria-label="Permalink to &quot;第四周&quot;">​</a></h1><h2 id="现代化的本质和铁律是什么" tabindex="-1">现代化的本质和铁律是什么？ <a class="header-anchor" href="#现代化的本质和铁律是什么" aria-label="Permalink to &quot;现代化的本质和铁律是什么？&quot;">​</a></h2><p>现代化的本质是自由市场经济和现代科学技术的结合时产生的经济无限累进增长的现象。全世界形成一个唯一的，统一的国际自由经济市场，离开这个市场代价越大。</p><h2 id="为什么现代化没有可能在中国诞生" tabindex="-1">为什么现代化没有可能在中国诞生？ <a class="header-anchor" href="#为什么现代化没有可能在中国诞生" aria-label="Permalink to &quot;为什么现代化没有可能在中国诞生？&quot;">​</a></h2><p>现代化诞生的最根本原因是在几乎无政府的状态下发展起来的自由市场经济。而中国自汉代的帝国建立以后，随着隋朝的制度创新，士大夫科举制的形成，中国的王权政权已经是全世界最发达、最稳固的政权体制，2000多年没有变化，甚至知道今天，让政府没有自己的政治意图，不参与经济活动也是不可能的。</p><h2 id="中西方历史文化最明显的差异是什么-背后的原因又是什么" tabindex="-1">中西方历史文化最明显的差异是什么？背后的原因又是什么？ <a class="header-anchor" href="#中西方历史文化最明显的差异是什么-背后的原因又是什么" aria-label="Permalink to &quot;中西方历史文化最明显的差异是什么？背后的原因又是什么？&quot;">​</a></h2><p>中国是政治贤能制的结果，每个人不论出身、可以靠自身努力获取政治权利的上升通道，因而可以动员所有人的力量，吸引着最卓越、最聪明的人进入政府工作。</p><p>西方是经济贤能制的结果，无论你是谁，出身如何，你在经济自由的通道，可以通过努力飞黄腾达，这种体系有助于释放个人和小集体（公司）的潜力，他吸引着人性的另一个方面，即个体性力量的释放。</p><h2 id="作者看来-中国近代现代化进程-78年后的经济腾飞-的原因是什么" tabindex="-1">作者看来，中国近代现代化进程（78年后的经济腾飞）的原因是什么？ <a class="header-anchor" href="#作者看来-中国近代现代化进程-78年后的经济腾飞-的原因是什么" aria-label="Permalink to &quot;作者看来，中国近代现代化进程（78年后的经济腾飞）的原因是什么？&quot;">​</a></h2><p>中国已经存在一个潜在的统一市场，还有着统一、稳定的政治环境。一旦真正开始接受现代文明的精髓，中国就像其他现代化国家一样开始蓬勃发展。</p><h2 id="了解现代化本质和中国现代化进程-对你实施定投有什么启示" tabindex="-1">了解现代化本质和中国现代化进程，对你实施定投有什么启示？ <a class="header-anchor" href="#了解现代化本质和中国现代化进程-对你实施定投有什么启示" aria-label="Permalink to &quot;了解现代化本质和中国现代化进程，对你实施定投有什么启示？&quot;">​</a></h2><p>现代化本质和中国现代化进程，是自由市场经济和现代科学技术相结合，符合趋势才能增长。</p>',59)])])}const k=e(r,[["render",h]]);export{u as __pageData,k as default};
